#include "../Source/PluginEditor.h"
#include "../Source/ExtendedPanel.h"
#include <iostream>
#include <stdexcept>

namespace {
void need(bool ok,const char* text){if(!ok)throw std::runtime_error(text);}
void set(SpaceInfinityProcessor& p,const juce::String& id,float v){auto* a=p.state.getParameter(id);need(a!=nullptr,"parameter exists");a->setValueNotifyingHost(a->convertTo0to1(v));}
juce::Component* find(juce::Component& c,const juce::String& name){if(c.getName()==name)return &c;for(auto* child:c.getChildren())if(auto* found=find(*child,name))return found;return nullptr;}
bool hasParameter(juce::Component& c,const juce::String& id){if(c.getProperties()["modParam"].toString()==id)return true;for(auto* child:c.getChildren())if(hasParameter(*child,id))return true;return false;}
}
int runUsabilitySmoke(){try{
    auto p=std::make_unique<SpaceInfinityProcessor>();auto editor=std::unique_ptr<juce::AudioProcessorEditor>(p->createEditor());editor->setSize(1000,790);
    auto* wheel=dynamic_cast<SpringPitchWheel*>(find(*editor,"Pitch Wheel"));need(wheel&&wheel->getMinimum()==-24&&wheel->getMaximum()==24,"wheel range is minus/plus 24");
    const auto mouse=[&](juce::Component* component){return juce::MouseEvent(juce::Desktop::getInstance().getMainMouseSource(),{12,12},juce::ModifierKeys(juce::ModifierKeys::leftButtonModifier),1,0,0,0,0,component,component,juce::Time::getCurrentTime(),{12,12},juce::Time::getCurrentTime(),1,true);};
    for(float pitch:{-24.0f,24.0f}){wheel->mouseDown(mouse(wheel));wheel->setValue(pitch,juce::sendNotificationSync);need(p->state.getRawParameterValue("pitchBend")->load()==pitch,"wheel reaches signed endpoints");wheel->mouseUp(mouse(wheel));need(p->state.getRawParameterValue("pitchBend")->load()==0,"mouse release centres host parameter");}
    set(*p,"pitchBend",12);need(wheel->getValue()==12,"host automation is not forcibly centred");set(*p,"pitchBend",0);
    auto* sub=dynamic_cast<juce::DragAndDropTarget*>(find(*editor,"Sub oscillator"));need(sub!=nullptr,"whole sub panel accepts LFO");juce::DragAndDropTarget::SourceDetails drag("INFINITY:LFO:0",editor.get(),{5,5});need(sub->isInterestedInDragSource(drag),"bass accepts LFO drag");sub->itemDropped(drag);need(p->modulationDepthFor("INFINITY:LFO:0","subLevel").isNotEmpty(),"bass drop creates adjustable level route");editor.reset();
    ExtendedPanel engine(*p);juce::TabbedComponent* tabs=nullptr;for(auto* child:engine.getChildren())if(auto* t=dynamic_cast<juce::TabbedComponent*>(child))tabs=t;need(tabs&&tabs->getNumTabs()==5,"five advanced engine tabs");
    bool grain=false,pitch=false,lab=false;for(int tab=0;tab<tabs->getNumTabs();++tab){tabs->setCurrentTabIndex(tab);for(const char* id:{"attack","ampDecay","ampSustain","release","filterAttack","filterDecay","filterSustain","filterRelease","glideTime","subLevel","pitchBend","analogueCharacter","filterInputDrive","convolverMix","wavetableScan"})need(!hasParameter(engine,id),"engine has no repeated main/FX knobs");grain|=hasParameter(engine,"grainSize");pitch|=hasParameter(engine,"pitchEnvAmount");lab|=hasParameter(engine,"analogueOscDrift");}need(grain&&pitch&&lab,"advanced controls retained");
    const auto capture=[&](bool digital,float character){p->loadPreset(0);set(*p,"engineMode",digital?1:0);set(*p,"analogueCharacter",character);set(*p,"analogueLabEnabled",1);for(const char* id:{"analogueOscDrift","analogueThermal","analogueFilterSpread","analogueVCADrive","analogueAsymmetry"})set(*p,id,character);set(*p,"attack",0);set(*p,"release",.03f);set(*p,"osc2Enabled",0);set(*p,"osc1PhaseReset",1);p->prepareToPlay(48000,256);juce::AudioBuffer<float> b(2,256);std::vector<float> result;for(int block=0;block<180;++block){juce::MidiBuffer midi;if(block==0)midi.addEvent(juce::MidiMessage::noteOn(1,60,.8f),0);p->processBlock(b,midi);for(int i=0;i<256;++i)result.push_back(b.getSample(0,i));}return result;};
    const auto clean=capture(true,0),bypassed=capture(true,.8f),analogue=capture(false,.8f);double same=0,different=0;for(size_t i=12000;i<clean.size();++i){same+=std::abs(clean[i]-bypassed[i]);different+=std::abs(clean[i]-analogue[i]);}std::cout<<"Mode deltas "<<same<<" / "<<different<<std::endl;need(same<.0001&&different>1,"digital bypasses variation; analogue changes real audio");
    const auto sweep=[&](bool match){p->loadPreset(0);set(*p,"engineMode",1);set(*p,"wave",0);set(*p,"osc2Enabled",0);set(*p,"osc1PhaseReset",1);set(*p,"cutoff",300);set(*p,"res",0);set(*p,"attack",0);set(*p,"ampSustain",1);set(*p,"release",.04f);set(*p,"levelMatch",match?1:0);p->prepareToPlay(48000,256);juce::AudioBuffer<float> b(2,256);double closed=0,opened=0;for(int block=0;block<600;++block){juce::MidiBuffer midi;if(block==0)midi.addEvent(juce::MidiMessage::noteOn(1,60,.8f),0);if(block==250)set(*p,"cutoff",12000);p->processBlock(b,midi);for(int ch=0;ch<2;++ch)for(int i=0;i<256;++i){const float v=b.getSample(ch,i);need(std::isfinite(v),"level match remains finite");if(block>=140&&block<240)closed+=v*v;if(block>=480&&block<580)opened+=v*v;}}
        if(match){std::array<double,8> levels{};for(int phrase=0;phrase<8;++phrase)for(int block=0;block<188;++block){juce::MidiBuffer midi;if(block==0){midi.addEvent(juce::MidiMessage::allNotesOff(1),0);midi.addEvent(juce::MidiMessage::noteOn(1,60,.8f),1);}if(block==110)midi.addEvent(juce::MidiMessage::allNotesOff(1),0);p->processBlock(b,midi);if(block>=40&&block<100)for(int ch=0;ch<2;++ch)for(int i=0;i<256;++i)levels[size_t(phrase)]+=b.getSample(ch,i)*b.getSample(ch,i);}const double ratio=(levels[6]+levels[7])/(levels[0]+levels[1]);std::cout<<"Level Match fresh-note energy ratio "<<ratio<<std::endl;need(ratio>.85&&ratio<1.2,"level match does not progressively fade fresh notes");}
        if(match){double a=0,c=0;const float master=p->state.getRawParameterValue("gain")->load();for(int block=0;block<400;++block){juce::MidiBuffer midi;if(block==0)midi.addEvent(juce::MidiMessage::noteOn(1,60,.8f),0);if(block==200)set(*p,"gain",master*.5f);p->processBlock(b,midi);for(int ch=0;ch<2;++ch)for(int i=0;i<256;++i){const double energy=b.getSample(ch,i)*b.getSample(ch,i);if(block>=100&&block<190)a+=energy;if(block>=300&&block<390)c+=energy;}}need(c/a>.22&&c/a<.29,"level match respects the final master gain");}
        return opened/closed;};
    const double natural=sweep(false),matched=sweep(true);std::cout<<"Filter-open energy ratios: natural "<<natural<<", matched "<<matched<<std::endl;need(natural>1.4&&matched<1.35&&matched>.65,"level match controls filter-opening volume");
    for(int preset:{0,1,2}){p->loadGatePreset(preset);studio::Rhythm gate;gate.prepare(48000);studio::Rhythm::Settings settings;settings.gate=true;settings.curveMode=p->state.getRawParameterValue("gateMode")->load()>.5f;settings.rate=int(p->state.getRawParameterValue("gateRate")->load());settings.attack=p->state.getRawParameterValue("gateAttack")->load();settings.release=p->state.getRawParameterValue("gateRelease")->load();for(int i=0;i<16;++i)settings.steps[size_t(i)]=p->state.getRawParameterValue("gateStep"+juce::String(i))->load();settings.smooth=1;settings.curveRate=int(p->state.getRawParameterValue("gateCurveRate")->load());settings.curve.count=int(p->state.getRawParameterValue("gateCurveCount")->load());for(int i=0;i<settings.curve.count;++i){settings.curve.x[size_t(i)]=p->state.getRawParameterValue("gateCurveX"+juce::String(i))->load();settings.curve.y[size_t(i)]=p->state.getRawParameterValue("gateCurveY"+juce::String(i))->load();settings.curve.bend[size_t(i)]=p->state.getRawParameterValue("gateCurveBend"+juce::String(i))->load();}gate.configure(settings,120);int pulses=0;float previous=0;for(int sample=0;sample<192000;++sample){const float value=gate.process(.3f,.3f,0)[0];if(sample>=96000&&previous<.15f&&value>=.15f)++pulses;previous=value;}need(pulses==(preset==0?16:preset==1?8:4),"classic gates have correct musical pulse counts");}
    {studio::Rhythm gate;gate.prepare(48000);studio::Rhythm::Settings settings;settings.gate=true;settings.delay=.1f;settings.fade=.2f;settings.attack=1;settings.release=1;settings.steps.fill(0);gate.configure(settings,120);double before=0,after=0;for(int i=0;i<24000;++i){const float v=gate.process(.3f,.3f,0)[0];if(i<2400)before+=v*v;if(i>21600)after+=v*v;}need(before>200&&after<.001,"gate delay passes dry sound then fade introduces gating");}
    set(*p,"engineMode",1);p->loadPreset(3);need(p->state.getRawParameterValue("engineMode")->load()==1,"overall mode persists across factory browsing");set(*p,"levelMatch",1);juce::MemoryBlock saved;p->getStateInformation(saved);p->loadPreset(0);p->setStateInformation(saved.getData(),int(saved.getSize()));need(p->state.getRawParameterValue("engineMode")->load()==1&&p->state.getRawParameterValue("levelMatch")->load()==1,"new switches survive project recall");
    std::cout<<"Spring wheel, bass drag/drop, duplicate removal, modes, level match and gate timings passed\n";return 0;
}catch(const std::exception& e){std::cerr<<"Usability: "<<e.what()<<std::endl;return 160;}}
